/usr/bin/bash -lc "python - <<'PY'
import asyncio
from contextlib import contextmanager

import anyio
import httpx2 as httpx

from starlette.testclient import _TestClientTransport


class Event:
    def __init__(self):
        self.value = False

    def is_set(self):
        return self.value

    def set(self):
        self.value = True

    async def wait(self):
        assert self.value


class Portal:
    def call(self, func, *args):
        if func is anyio.Event:
            return Event()
        return asyncio.run(func(*args))


@contextmanager
def portal_factory():
    yield Portal()


async def request(info):
    async def app(scope, receive, send):
        await send({\"type\": \"http.response.debug\", \"info\": info})
        await send({\"type\": \"http.response.start\", \"status\": 200, \"headers\": []})
        await send({\"type\": \"http.response.body\", \"body\": b\"ok\"})

    transport = _TestClientTransport(
        app,
        portal_factory,
        client=(\"testclient\", 50000),
        app_state={},
    )
    return transport.handle_request(httpx.Request(\"GET\", \"http://testserver/\"))


arbitrary = {\"foo\": \"bar\", \"nested\": {\"answer\": 42}}
response = asyncio.run(request(arbitrary))
assert response.extensions[\"http.response.debug\"] == arbitrary
assert not hasattr(response, \"template\")
assert not hasattr(response, \"context\")

template = object()
context = {\"request\": object()}
with_template = {\"template\": template, \"context\": context, \"foo\": \"bar\"}
response = asyncio.run(request(with_template))
assert response.extensions[\"http.response.debug\"] == with_template
assert response.template is template
assert response.context is context
print(\"transport debug response behavior verified\")
PY"

